select e.groupe, e.path, e.pg_id, e.type_id,
       (c.type_id is not null) as cache_r8_present, c.stale,
       exists (select 1 from jsonb_array_elements(c.payload->'catalog'->'families') f,
                    jsonb_array_elements(f->'gammes') g where (g->>'pg_id')::int = e.pg_id) as gamme_dans_catalogue_r8,
       (select jsonb_array_length(c.payload->'catalog'->'families')) as n_familles,
       (select min(g.ord) from jsonb_array_elements(c.payload->'catalog'->'families') f,
               jsonb_array_elements(f->'gammes') with ordinality g(v, ord) where (g.v->>'pg_id')::int = e.pg_id) as rang_dans_famille
